import { canonicalIp, cleanLineSetting, parseIpList } from './reader-inbound.js';
// Settings of the reader accounts and their SMS budget. They live in the `settings` table like the other site settings;
// a row that was never written (or was damaged by hand) falls back to the default here, so the migration does not need
// to insert any.
//
// The API talks in short names (`signup_enabled`); the table keys are the long ones.
//
// The secret of the inbound-SMS webhook (`reader_inbound_key`) is deliberately NOT a field here: it is generated by the server,
// never typed, never part of the settings object (so it cannot leak through a settings answer or the public config), and
// refused as an unknown name if a request tries to set it. See INBOUND_KEY_SETTING below.
export const READER_AUTH_METHODS = Object.freeze(['sms_send', 'sms_receive']);
export const INBOUND_KEY_SETTING = 'reader_inbound_key';

export const READER_SETTING_DEFAULTS = Object.freeze({
  reader_signup_enabled: '0',
  reader_auth_method: 'sms_send',
  reader_inbound_line: '',
  reader_inbound_ips: '',
  sms_cost_rial: '2000',
  sms_min_remaining: '200',
  sms_daily_cap: '300',
});

const FIELDS = Object.freeze({
  signup_enabled: { key: 'reader_signup_enabled', kind: 'boolean', label: 'ثبت‌نام خوانندگان' },
  // sms_send: we send the code through ippanel (the original behaviour, costs one SMS per login).
  // sms_receive: the reader sends an SMS from their own SIM to our receiving line (no cost per login).
  auth_method: { key: 'reader_auth_method', kind: 'enum', values: READER_AUTH_METHODS, label: 'روش ورود' },
  // Only used by sms_receive: our receiving line (digits), and the addresses allowed to call the webhook (empty: any).
  inbound_line: { key: 'reader_inbound_line', kind: 'line', label: 'شمارهٔ خط دریافت' },
  inbound_ips: { key: 'reader_inbound_ips', kind: 'ips', max: 20, label: 'نشانی‌های مجاز وب‌هوک' },
  // What one pattern SMS is assumed to cost. The real price is a little lower (about 1,848 rial), so estimates stay on the safe side.
  sms_cost_rial: { key: 'sms_cost_rial', kind: 'integer', min: 100, max: 100_000, label: 'هزینهٔ هر پیامک (ریال)' },
  // Below this many SMS left (credit / cost), signup switches itself off.
  sms_min_remaining: { key: 'sms_min_remaining', kind: 'integer', min: 0, max: 100_000, label: 'حداقل پیامک باقی‌مانده' },
  sms_daily_cap: { key: 'sms_daily_cap', kind: 'integer', min: 1, max: 100_000, label: 'سقف روزانهٔ پیامک' },
});

export const READER_SETTING_KEYS = Object.freeze(Object.values(FIELDS).map((field) => field.key));

const faNumber = new Intl.NumberFormat('fa-IR');

function parseStored(field, raw) {
  if (field.kind === 'boolean') return raw === '1';
  if (field.kind === 'enum') return field.values.includes(raw) ? raw : READER_SETTING_DEFAULTS[field.key]; // a damaged row falls back to the safe default
  if (field.kind === 'line') return cleanLineSetting(raw) ?? '';
  if (field.kind === 'ips') return parseIpList(raw).map(canonicalIp).filter(Boolean);
  const number = Number(raw);
  return Number.isInteger(number) && number >= field.min && number <= field.max ? number : Number(READER_SETTING_DEFAULTS[field.key]);
}

// rows: [{ k, v }] from the settings table. Always returns every field, filled from the defaults where needed.
export function readerSettingsFromRows(rows = []) {
  const stored = Object.fromEntries(rows.map((row) => [row.k, row.v]));
  return Object.fromEntries(Object.entries(FIELDS).map(([name, field]) => [name, parseStored(field, stored[field.key] ?? READER_SETTING_DEFAULTS[field.key])]));
}

export async function loadReaderSettings(pool) {
  const [rows] = await pool.query('SELECT k, v FROM settings WHERE k IN (?)', [READER_SETTING_KEYS]);
  return readerSettingsFromRows(rows);
}

// body: what the super admin's panel sent. Strict on purpose: unknown names, strings instead of numbers and
// out-of-range numbers are refused instead of being corrected.
export function validateReaderSettingsUpdate(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return { ok: false, error: 'تنظیمات ارسالی معتبر نیست.' };
  const names = Object.keys(body);
  if (!names.length || names.some((name) => !Object.hasOwn(FIELDS, name))) return { ok: false, error: 'تنظیمات ارسالی معتبر نیست.' };
  const values = {};
  for (const name of names) {
    const field = FIELDS[name];
    const value = body[name];
    if (field.kind === 'boolean') {
      if (typeof value !== 'boolean') return { ok: false, error: `مقدار «${field.label}» باید روشن یا خاموش باشد.` };
    } else if (field.kind === 'enum') {
      if (typeof value !== 'string' || !field.values.includes(value)) return { ok: false, error: `«${field.label}» باید یکی از دو حالت «ارسال کد از طرف ما» یا «ارسال پیامک از طرف خواننده» باشد.` };
    } else if (field.kind === 'line') {
      // '' clears the line; anything else must be 8 to 16 digits (Persian digits are converted).
      if (typeof value !== 'string') return { ok: false, error: `«${field.label}» باید فقط رقم باشد (۸ تا ۱۶ رقم).` };
      const line = value.trim() === '' ? '' : cleanLineSetting(value);
      if (line === null) return { ok: false, error: `«${field.label}» باید فقط رقم باشد (۸ تا ۱۶ رقم)، مثلاً ۹۸۵۰۰۰۲۶۲۷۲۰.` };
      values[name] = line;
      continue;
    } else if (field.kind === 'ips') {
      if (!Array.isArray(value) || value.length > field.max || value.some((item) => typeof item !== 'string')) return { ok: false, error: `«${field.label}» باید فهرستی از حداکثر ${faNumber.format(field.max)} نشانی IP باشد.` };
      const ips = [];
      for (const item of value) {
        const ip = canonicalIp(item);
        if (!ip) return { ok: false, error: `«${field.label}»: یکی از نشانی‌ها IP معتبر نیست.` };
        if (!ips.includes(ip)) ips.push(ip);
      }
      values[name] = ips;
      continue;
    } else if (!Number.isInteger(value) || value < field.min || value > field.max) {
      return { ok: false, error: `«${field.label}» باید عددی صحیح بین ${faNumber.format(field.min)} و ${faNumber.format(field.max)} باشد.` };
    }
    values[name] = value;
  }
  return { ok: true, values };
}

export function storedValue(name, value) {
  const { kind } = FIELDS[name];
  if (kind === 'boolean') return value ? '1' : '0';
  if (kind === 'ips') return value.join(',');
  return String(value);
}

// The one place that reads the webhook secret. Never put the result in a log, an event, a settings answer or the public config.
export async function loadInboundKey(pool) {
  const [rows] = await pool.query('SELECT k, v FROM settings WHERE k IN (?)', [[INBOUND_KEY_SETTING]]);
  const value = rows.find((row) => row.k === INBOUND_KEY_SETTING)?.v;
  return typeof value === 'string' && /^[a-f0-9]{64}$/.test(value) ? value : null;
}

export const readerSettingKey = (name) => FIELDS[name].key;
